import { readFileSync, realpathSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export function planRedactions(text, rules) {
  if (typeof text !== 'string' || !Array.isArray(rules)) {
    throw new Error('Expected a string text and an array of rules');
  }

  // Validate and snapshot every rule before looking for any occurrences.
  const validated = [];
  const ids = new Set();
  for (let index = 0; index < rules.length; index++) {
    if (!Object.hasOwn(rules, index)) {
      throw new Error('Rules must be a dense array');
    }
    const rule = rules[index];
    if (rule === null || typeof rule !== 'object' || Array.isArray(rule)) {
      throw new Error(`Invalid rule at index ${index}`);
    }
    const { id, literal, replacement } = rule;
    if (typeof id !== 'string' || id.length === 0 || ids.has(id) ||
        typeof literal !== 'string' || literal.length === 0 ||
        typeof replacement !== 'string') {
      throw new Error(`Invalid rule fields at index ${index}`);
    }
    ids.add(id);
    validated.push({ id, literal, replacement });
  }

  const matches = [];
  for (let index = 0; index < validated.length; index++) {
    const { literal } = validated[index];
    let start = text.indexOf(literal);
    while (start !== -1) {
      matches.push({ start, end: start + literal.length, index });
      // Advance one UTF-16 code unit so overlapping occurrences are included.
      start = text.indexOf(literal, start + 1);
    }
  }
  matches.sort((a, b) => a.start - b.start || b.end - a.end || a.index - b.index);

  const edits = [];
  const parts = [];
  let cursor = 0;
  for (const { start, end, index } of matches) {
    if (start < cursor) continue;
    const { id, replacement } = validated[index];
    parts.push(text.slice(cursor, start), replacement);
    edits.push({ start, end, id });
    cursor = end;
  }
  parts.push(text.slice(cursor));
  const result = parts.join('');
  return {
    text: result,
    edits,
    originalBytes: Buffer.byteLength(text, 'utf8'),
    redactedBytes: Buffer.byteLength(result, 'utf8'),
  };
}

function isMain() {
  if (!process.argv[1]) return false;
  try {
    return realpathSync(process.argv[1]) === fileURLToPath(import.meta.url);
  } catch {
    return false;
  }
}

if (isMain()) {
  try {
    if (process.argv.length !== 3) {
      throw new Error('Usage: node redaction-plan.js INPUT_JSON_FILE');
    }
    const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    if (input === null || typeof input !== 'object' || Array.isArray(input)) {
      throw new Error('Input JSON must be an object containing text and rules');
    }
    const result = planRedactions(input.text, input.rules);
    process.stdout.write(`${JSON.stringify(result)}\n`);
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
}

