import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { planRedactions } from '../redaction-plan.js';

const rule = (id, literal, replacement = '') => ({ id, literal, replacement });

test('overlaps, touching edits, and same-length ties use source ordering', () => {
  assert.deepEqual(planRedactions('ababa', [rule('long', 'aba', 'X'), rule('short', 'ba', 'Y')]), {
    text: 'XY', edits: [{ start: 0, end: 3, id: 'long' }, { start: 3, end: 5, id: 'short' }],
    originalBytes: 5, redactedBytes: 2,
  });
  assert.deepEqual(planRedactions('aaaaa', [rule('first', 'aa', 'X'), rule('second', 'aa', 'Y')]).edits,
    [{ start: 0, end: 2, id: 'first' }, { start: 2, end: 4, id: 'first' }]);
  assert.equal(planRedactions('abc', [rule('later', 'bc', 'Y'), rule('early', 'a', 'X')]).text, 'XY');
});

test('literals and replacements are exact and replacements are not rescanned', () => {
  assert.equal(planRedactions('A a.b aXb', [rule('dot', 'a.b', '$&a'), rule('a', 'a', 'Z')]).text,
    'A $&a ZXb');
});

test('UTF-16 offsets and UTF-8 byte counts include surrogate edge cases', () => {
  assert.deepEqual(planRedactions('é😀z', [rule('emoji', '😀', '界')]), {
    text: 'é界z', edits: [{ start: 1, end: 3, id: 'emoji' }], originalBytes: 7, redactedBytes: 6,
  });
  const result = planRedactions('😀', [rule('half', '\ud83d')]);
  assert.deepEqual(result, {
    text: '\ude00', edits: [{ start: 0, end: 1, id: 'half' }], originalBytes: 4, redactedBytes: 3,
  });
});

test('frozen rules, opaque IDs, and ignored extra fields work', () => {
  const rules = Object.freeze([
    Object.freeze({ ...rule('__proto__', 'a', 'b'), extra: true }),
    Object.freeze(rule('constructor', 'b', 'c')),
  ]);
  assert.deepEqual(planRedactions('ab', rules), {
    text: 'bc', edits: [{ start: 0, end: 1, id: '__proto__' }, { start: 1, end: 2, id: 'constructor' }],
    originalBytes: 2, redactedBytes: 2,
  });
  assert.equal(rules[0].replacement, 'b');
});

test('invalid inputs are rejected even with empty text', () => {
  for (const text of [null, undefined, 0, {}, [], new String('a')]) {
    assert.throws(() => planRedactions(text, []), Error);
  }
  const invalid = [null, {}, 'rules', [null], [[]], [1], [undefined], new Array(1),
    [rule('', 'a')], [rule('x', '')], [rule(1, 'a')], [rule('x', 1)],
    [{ id: 'x', literal: 'a' }], [rule('x', 'a', null)],
    [rule('__proto__', 'a'), rule('__proto__', 'b')],
    [rule('valid', 'a'), rule('bad', '')]];
  for (const rules of invalid) assert.throws(() => planRedactions('', rules), Error);
  assert.deepEqual(planRedactions('', []), { text: '', edits: [], originalBytes: 0, redactedBytes: 0 });
});

const cli = fileURLToPath(new URL('../redaction-plan.js', import.meta.url));
test('CLI has exact success output and clean error behavior', () => {
  const directory = mkdtempSync(join(tmpdir(), 'redaction-plan-'));
  const file = join(directory, 'input.json');
  const run = (args) => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });
  const fails = (args) => {
    const result = run(args);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length > 0);
  };
  try {
    const input = { text: 'ababa', rules: [rule('long', 'aba', 'X'), rule('short', 'ba', 'Y')], extra: 1 };
