    fails([file, file]);
    fails([join(directory, 'missing.json')]);
    fails([directory]);
    for (const content of ['{', 'null', '[]', '42', '{}', '{"text":"","rules":[null]}']) {
      writeFileSync(file, content);
      fails([file]);
    }
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
});

